// LA CONSOLA MANDA: si el panel contesta, sus valores pisan a los de
// `Config base`; si no contesta, se usan los de respaldo. Mismo nombre y misma
// regla que en los flujos de los demos, y por el mismo motivo: las expresiones
// del flujo buscan «Config del negocio».
//
// EL 409 NO ES UN FALLO: ES LA RESPUESTA QUE CORTA EL SERVICIO. El nodo HTTP
// devuelve la respuesta completa -codigo y cuerpo- y aca se decide con el
// codigo (ver `estado-comercio.test.ts`):
//
//   200 + tenantId  -> configuracion del panel
//   409             -> SUSPENDIDO. Es una respuesta valida, no un error.
//   cualquier otra  -> no se pudo saber -> respaldo, y se sigue atendiendo:
//                      una caida del panel no deja a un prospecto sin respuesta.
//
// LO PROPIO DE ESTE FLUJO viene en `onboarding` (el documento
// /config/onboarding, que edita el administrador del comercio (y el propietario)): el mensaje
// para quien ya es cliente, el enlace a la consola, el fin del primer bloque,
// la plantilla del aviso interno y LA OFERTA -- rubros, planes, cargos unicos,
// aclaraciones y el archivo de planes --. Cada valor se valida ACA TAMBIEN:
// ante la duda gana el respaldo, y un elemento mal formado se descarta.
//
// LA OFERTA LA MANDA LA CONSOLA, ENTERA. Si el panel contesto, sus listas valen
// aunque vengan vacias: sin planes cargados el asistente no da precios, ofrece
// un asesor. El corpus del sitio (`Conocimiento del sitio`) sigue para todo lo
// demas, y si dice otra cosa sobre precios, gana la consola.
//
// EL HORARIO TAMBIEN MANDA VACIO. NovuChat no tiene horario fijo: si el panel
// contesto con el horario vacio, NO se cae al respaldo de `Config base` -- que
// seria un horario que nadie cumple -- y ni el prompt ni el traspaso lo mencionan.
//
// EL TECHO DE COSTO NO LO PONE ESTE FLUJO: lo pone el servidor, igual que en
// los flujos A y B. `configuracionFlujo` devuelve en `atencion` el estado del
// telefono -- normal, operador o bloqueado -- segun los umbrales de la cuenta
// (`atencion.ts`), y el flujo lo obedece antes de llamar al modelo. Aca solo se
// lee y se valida; quien decide es el servidor.
//
// EL LARGO MAXIMO DEL CUERPO DE UN MENSAJE CON BOTONES (1024) ES DE META Y
// VIVE EN UN SOLO LUGAR DEL FLUJO: `limiteInteractivo` de `Config base`. Aca se
// valida y viaja con el resto de la configuracion, porque lo necesitan dos
// nodos que corren despues: `Procesar respuesta` -- que compacta para que el
// boton sobreviva -- y `Salida` -- que baja el mensaje a texto si ni asi entra --.
//
// AL FINAL SE DERIVAN LOS TEXTOS QUE USAN LAS INSTRUCCIONES DEL AGENTE (la
// presentacion, la oferta, las aclaraciones, la frase del horario). Dependen
// solo de la configuracion, no del turno: las instrucciones siguen fijas entre
// un mensaje y otro, y el proveedor las puede cachear.
const base = $('Config base').first().json;

const respuesta = $input.first().json ?? {};
const codigo = Number(respuesta.statusCode);
const cuerpo = (respuesta.body ?? {});

const util = (v) => (typeof v === 'string' && v.trim() !== '') ? v.trim() : undefined;
const soloLlenos = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined));
const entero = (v, min, max) => (Number.isInteger(v) && v >= min && v <= max) ? v : undefined;

// Texto de la consola que va al prompt o a un mensaje: una linea, sin corchetes
// (no puede fingir una marca como [CIERRE]) ni los delimitadores del corpus.
const linea = (v, max) => String(v ?? '')
  .replace(/<<<|>>>/g, '').replace(/[\[\]{}]/g, '')
  .replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, max);
// Un marcador sin llenar (`REEMPLAZAR_…`) no es un valor.
const valor = (v) => (typeof v === 'string' && !/^REEMPLAZAR_/.test(v.trim())) ? v.trim() : '';
// `Config base` es un Set: una lista puede llegar como texto JSON.
const lista = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') { try { const j = JSON.parse(v); return Array.isArray(j) ? j : []; } catch (err) { return []; } }
  return [];
};
const precio = (v) => (typeof v === 'number' && Number.isFinite(v) && v >= 0 && v < 100000) ? v : undefined;

const NIVELES = ['ninguno', 'pocos', 'muchos'];
const PERIODOS = ['mes', 'anio', 'unico'];

function limpiarOferta(ob) {
  const rubros = lista(ob.rubros).map((r) => ({
    id: linea(r?.id, 40), nombre: linea(r?.nombre, 60),
    solucion: linea(r?.solucion, 400), flujoSugerido: linea(r?.flujoSugerido, 40),
  })).filter((r) => r.id && r.nombre).slice(0, 20);
  // El rubro «a medida» va al final, como la salida de la lista.
  const aMedida = (r) => /medida|^otro/i.test(r.id + ' ' + r.nombre);
  const ordenados = [...rubros.filter((r) => !aMedida(r)), ...rubros.filter(aMedida)];

  const planes = lista(ob.planes).map((p) => ({
    nombre: linea(p?.nombre, 40), precioUsd: precio(p?.precioUsd),
    periodo: PERIODOS.includes(p?.periodo) ? p.periodo : '', incluye: linea(p?.incluye, 200),
  })).filter((p) => p.nombre && p.precioUsd !== undefined && p.periodo).slice(0, 12);

  const cargosUnicos = lista(ob.cargosUnicos).map((c) => ({
    nombre: linea(c?.nombre, 40), precioUsd: precio(c?.precioUsd),
    desde: c?.desde === true, detalle: linea(c?.detalle, 200),
  })).filter((c) => c.nombre && c.precioUsd !== undefined).slice(0, 6);

  const aclaraciones = lista(ob.aclaraciones).map((a) => ({
    tema: linea(a?.tema, 60), texto: linea(a?.texto, 600),
  })).filter((a) => a.tema && a.texto).slice(0, 15);

  const ap = ob.archivoPlanes && typeof ob.archivoPlanes === 'object' ? ob.archivoPlanes : null;
  const url = ap ? String(ap.url ?? '').trim() : '';
  const archivoPlanes = ap && /^https:\/\/\S+$/.test(url) && ['pdf', 'imagen'].includes(ap.tipo)
    ? { url, tipo: ap.tipo, nombreArchivo: linea(ap.nombreArchivo, 80) || 'Planes.pdf' } : null;
  // Sin un archivo valido no hay encabezado que mandar: se listan igual.
  const planesEnArchivo = ob.planesEnArchivo === true && archivoPlanes !== null;

  return { rubros: ordenados, planes, cargosUnicos, aclaraciones, archivoPlanes, planesEnArchivo };
}

// El fin del primer bloque del respaldo, como numero. El Set lo guarda como
// numero, pero un export editado a mano podria traerlo como texto.
const baseAviso = Number(base.topeAviso) || 25;

// ESTADO DE ATENCION DEL TELEFONO (servidor). Sin respuesta del panel, `normal`:
// una caida del panel no deja sin respuesta a un prospecto.
const at = (codigo === 200 && cuerpo && typeof cuerpo.atencion === 'object' && cuerpo.atencion)
  ? cuerpo.atencion : {};
const atencion = {
  atencionEstado: ['normal', 'operador', 'bloqueado'].includes(at.estado) ? at.estado : 'normal',
  atencionAvisarRecepcion: ['operador', 'bloqueado'].includes(at.avisarRecepcion) ? at.avisarRecepcion : '',
  // Respuestas del asistente YA enviadas en la ventana. `null` si no se sabe.
  atencionRespuestas: (typeof at.respuestasEnVentana === 'number' && Number.isFinite(at.respuestasEnVentana))
    ? at.respuestasEnVentana : null,
  atencionVenceEn: util(at.ventanaVenceEn) || '',
};

// Respaldo de la oferta y de la voz: lo que trae `Config base`.
const ofertaBase = limpiarOferta({
  rubros: base.rubros, planes: base.planes, cargosUnicos: base.cargosUnicos,
  aclaraciones: base.aclaraciones, archivoPlanes: null, planesEnArchivo: false,
});
const respaldo = {
  ...base,
  ...ofertaBase,
  // Limite del cuerpo interactivo (Meta). Un export editado a mano podria
  // traerlo como texto, en cero o sin el campo: ahi manda el valor de siempre.
  limiteInteractivo: entero(Number(base.limiteInteractivo), 200, 4096) ?? 1024,
  nombreAsistente: linea(valor(base.nombreAsistente), 40),
  nivelEmojis: NIVELES.includes(base.nivelEmojis) ? base.nivelEmojis : 'pocos',
  horarioAtencion: linea(valor(base.horarioAtencion), 120),
};

// TEXTOS DERIVADOS de la configuracion final, para las instrucciones del
// agente y las ramas sin modelo. Ver el comentario de arriba.
const monto = (n) => Number.isInteger(n) ? String(n) : n.toFixed(2).replace('.', ',');
const SUFIJO = { mes: '/mes', anio: '/año', unico: ', pago único' };
function derivar(c) {
  const negocio = c.nombreNegocio || 'NovuChat';
  const presentacion = (c.nombreAsistente ? c.nombreAsistente + ', ' : '') + 'el asistente virtual de ' + negocio;
  // NUMERADOS, Y ESO NO CONTRADICE QUE AL CLIENTE SE LE MUESTREN COMO
  // REFERENCIA. Esta lista la lee el MODELO, no el cliente: lo que el cliente
  // ve lo arma `Procesar respuesta`, en linea y sin numerar. Se probo quitarle
  // los numeros tambien aca, suponiendo que numerados el modelo los numeraria
  // en el chat, y la medicion dijo lo contrario (`scripts/comparar-prompt.mjs`,
  // 30 corridas por version contra gemini-3.5-flash-lite, 22/09/2026):
  //   rubrosTexto numerado    -> [RUBROS] en 83 %, y le pide un numero al
  //                              cliente en 0 de 30
  //   rubrosTexto sin numerar -> [RUBROS] en 10-37 %
  //   (la version de antes del 22/09, con la lista numerada TAMBIEN en el
  //    chat, ponia la marca en el 50-73 % y le pedia un numero al cliente en
  //    el 20 % de los turnos, que es justo lo que se quiso sacar)
  // Sin los numeros el modelo deja de reconocer la lista como algo que se
  // muestra. El temor de que numerara en el chat no se verifico ni una vez.
  const rubrosTexto = c.rubros.length
    ? c.rubros.map((r, i) => (i + 1) + '. ' + r.nombre +
        (r.solucion ? ' - solución: ' + r.solucion : '')).join('\n')
    : '(no hay rubros cargados: pregúntale a qué se dedica su negocio, sin lista)';
  const planesTexto = c.planes.length
    ? c.planes.map((p) => p.nombre + ' (USD ' + monto(p.precioUsd) + SUFIJO[p.periodo] + ')' +
        (p.incluye ? ': ' + p.incluye : '')).join('\n')
    : '(no hay planes cargados: no des ningún precio; ofrece que un asesor se los confirme)';
  const cargosTexto = c.cargosUnicos.length
    ? c.cargosUnicos.map((x) => x.nombre + ' (pago único): ' + (x.desde ? 'desde ' : '') + 'USD ' +
        monto(x.precioUsd) + (x.detalle ? '. ' + x.detalle : '')).join('\n')
    : '(ninguno)';
  const aclaracionesTexto = c.aclaraciones.length
    ? c.aclaraciones.map((a) => '- ' + a.tema + ': ' + a.texto).join('\n')
    : '(ninguna)';
  const h = c.horarioAtencion;
  return { ...c,
    presentacion,
    rubrosTexto, planesTexto, cargosTexto, aclaracionesTexto,
    // Cuando escribe una persona del equipo. Sin horario, «lo antes posible».
    fraseContacto: h ? 'en horario de atención (' + h + ')' : 'lo antes posible',
    lineaHorario: h
      ? 'Las personas del equipo atienden en este horario: ' + h + '.'
      : 'Las personas del equipo responden lo antes posible, sin días ni horas fijos: no prometas ninguno.',
  };
}

if (codigo === 409) {
  return [{ json: derivar({ ...respaldo, ...atencion,
    topeAviso: baseAviso,
    estadoComercio: 'suspendido',
    // Texto neutro del panel: no menciona pagos ni deudas.
    mensajeComercioSuspendido: util(cuerpo.mensajeCortesia) || base.mensajeComercioSuspendido,
    configDeLaConsola: false,
    panelDice: 'no operativo',
  }) }];
}

const contesto = codigo === 200 && cuerpo && typeof cuerpo.tenantId === 'string';
if (!contesto) {
  return [{ json: derivar({ ...respaldo, ...atencion,
    topeAviso: baseAviso,
    estadoComercio: base.estadoComercio ?? 'operativo',
    configDeLaConsola: false,
    panelSinRespuesta: true,
    codigoDelPanel: Number.isFinite(codigo) ? codigo : 0,
  }) }];
}

const r = cuerpo;
const dn = r.datosDelNegocio ?? {};
const op = r.operacion ?? {};
const ob = r.onboarding ?? {};
const voz = r.voz ?? {};

const topeAviso = entero(ob.topeAviso, 3, 100) ?? baseAviso;

const enlace = util(ob.enlaceConsola);
const plantilla = util(ob.plantillaAviso);
const recepcion = util(op.numeroRecepcion);

const deLaConsola = soloLlenos({
  nombreNegocio: util(dn.nombreNegocio),
  // Solo digitos: es el destino de la plantilla y del boton a una persona.
  numeroRecepcion: recepcion ? (recepcion.replace(/\D/g, '') || undefined) : undefined,
  phoneNumberId: util(r.phoneNumberId),
  zonaHoraria: util(op.zonaHoraria),
  // La voz sale ROTULADA del panel (`voz`), no por posicion del arreglo.
  tratamiento: util(voz.tratamiento),
  estiloEmojis: util(voz.emojis),
  nivelEmojis: NIVELES.includes(voz.nivelEmojis) ? voz.nivelEmojis : undefined,
  mensajeClienteActual: util(ob.mensajeClienteActual),
  enlaceConsola: enlace && /^https:\/\//.test(enlace) ? enlace : undefined,
  plantillaAviso: plantilla && /^[a-z0-9_]{1,64}$/.test(plantilla) ? plantilla : undefined,
});

// El estado siempre sale del panel: es lo que corta el servicio.
const estadoComercio = util(r.estadoComercio) === 'activo' ? 'operativo'
  : (util(r.estadoComercio) ? 'suspendido' : (base.estadoComercio ?? 'operativo'));

return [{ json: derivar({
  ...respaldo,
  ...deLaConsola,
  // Mandan aunque vengan vacios (ver arriba): el nombre del asistente, el
  // horario y la oferta entera.
  nombreAsistente: linea(voz.nombreAsistente, 40),
  horarioAtencion: linea(op.horarioAtencion, 120),
  ...limpiarOferta(ob),
  ...atencion,
  topeAviso,
  estadoComercio,
  configDeLaConsola: true,
}) }];

// Normaliza el payload de la Cloud API (regla "normalizacion de entrada" de
// CLAUDE.md) y arrastra lo que puso `Config del negocio`. Nunca se accede a
// `.text.body` fuera de este nodo.
//
// LO PROPIO DE ESTE FLUJO:
//  - `eleccion`: lo que el cliente eligio en un boton de respuesta. Los de la
//    bienvenida (`cliente_actual` / `cliente_nuevo`) y el de «Hablar con un
//    asesor» (`asesor`), que sale con los planes y al fin del primer bloque.
//    Tambien se reconocen ESCRITOS: quien contesta «ya soy cliente» o «quiero
//    hablar con un asesor» no tiene que tocar el boton. Y si Meta rechazo el
//    interactivo, el texto de respaldo le pide justamente que lo escriba.
//  - `anuncio`: si el mensaje viene de un anuncio de clic a WhatsApp, Meta manda
//    `referral`. Sirve para que el asistente sepa por que escribe la persona, y
//    para medir la ventana de punto de entrada gratuito (CLAUDE.md §6).
//  - Una imagen o un documento NO se asumen como comprobante: este flujo no
//    cobra. Se pide que lo escriba.
const CLIENTE_ACTUAL = /\b(ya\s+soy\s+cliente|soy\s+cliente(\s+de\s+novuchat)?|ya\s+tengo\s+(novuchat|el\s+asistente|la\s+consola)|mi\s+consola|entrar\s+a\s+(la\s+|mi\s+)?consola|mi\s+cuenta\s+de\s+novuchat)\b/i;
// El mensaje ENTERO es el pedido: «asesor», «quiero hablar con un asesor».
// Una pregunta que solo menciona al asesor («¿el asesor me llama?») sigue al
// asistente.
const ASESOR = /^\s*(quiero\s+|me\s+gustar[ií]a\s+|deseo\s+|prefiero\s+)?(hablar\s+con\s+)?(un\s+|una\s+|el\s+|la\s+)?(asesor|asesora|especialista)(\s+por\s+favor)?[\s.!¡]*$/i;
const SALUDO = /^(hola|ola|buen(a|o)s?( d[ií]as| tardes| noches)?|hey|holi|qu[eé] tal|saludos)[\s!¡.,?¿👋🙂😊]*$/i;

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const src = items[i].json;

  // Config viene mezclada con el payload de Meta: se separa sin listar campo
  // por campo. `conocimiento` se descarta: son 16 mil caracteres que el agente
  // lee directo de su nodo, y no tienen por que viajar en cada item.
  const cfg = { ...src };
  for (const k of ['messages', 'contacts', 'statuses', 'errors', 'metadata',
                   'messaging_product', 'conocimiento']) {
    delete cfg[k];
  }

  const msg = Array.isArray(src.messages) ? src.messages[0] : undefined;
  if (!msg) continue; // acuse de estado u otro evento: no deberia llegar aca

  const tipo = msg.type ?? 'desconocido';
  let userInput = '';
  let esSaludo = false;
  let eleccion = '';

  switch (tipo) {
    case 'text': {
      userInput = msg.text?.body ?? '';
      esSaludo = SALUDO.test(userInput.trim());
      if (CLIENTE_ACTUAL.test(userInput)) eleccion = 'cliente_actual';
      else if (ASESOR.test(userInput)) eleccion = 'asesor';
      break;
    }
    case 'interactive': {
      const r = msg.interactive?.button_reply ?? msg.interactive?.list_reply;
      const id = String(r?.id ?? '');
      if (id === 'cliente_actual' || id === 'cliente_nuevo' || id === 'asesor') eleccion = id;
      userInput = id === 'cliente_nuevo' ? 'Quiero conocer NovuChat.'
        : id === 'cliente_actual' ? 'Ya soy cliente de NovuChat.'
        : id === 'asesor' ? 'Quiero hablar con un asesor.'
        : 'El cliente toco: ' + (r?.title ?? '') + '. Tomalo como si te lo hubiera escrito.';
      break;
    }
    case 'button': {
      userInput = 'El cliente pulso el boton: ' + (msg.button?.text ?? '');
      break;
    }
    case 'image':
    case 'document':
    case 'video': {
      const cap = msg[tipo]?.caption ? ' Escribio junto al archivo: "' + msg[tipo].caption + '".' : '';
      userInput = 'AVISO_SISTEMA: el cliente envio un archivo (' + tipo + ') que no puedes ver.' + cap +
        ' Pidele con amabilidad que te escriba en texto lo que necesita.';
      break;
    }
    case 'audio':
    case 'voice': {
      userInput = 'AVISO_SISTEMA: el cliente envio una NOTA DE VOZ que no puedes escuchar. ' +
        'Pidele con amabilidad que te lo escriba.';
      break;
    }
    case 'location': {
      const loc = msg.location ?? {};
      userInput = 'AVISO_SISTEMA: el cliente compartio una ubicacion' +
        (loc.address ? ' (' + loc.address + ')' : '') +
        '. Si es la de su negocio, agradecela y sigue la conversacion.';
      break;
    }
    case 'sticker':
    case 'contacts':
    default: {
      userInput = 'AVISO_SISTEMA: el cliente envio un mensaje de tipo "' + tipo +
        '" que no puedes leer. Respondele con cortesia que por ahora atiendes por texto.';
    }
  }

  const ref = msg.referral;
  const anuncio = ref ? {
    titular: String(ref.headline ?? '').slice(0, 120),
    fuente: String(ref.source_type ?? ''),
    url: String(ref.source_url ?? '').slice(0, 200),
  } : null;

  const contacto = Array.isArray(src.contacts) ? src.contacts[0] : undefined;

  out.push({ json: Object.assign({}, cfg, {
    userInput,
    tipo,
    esSaludo,
    eleccion,
    anuncio,
    from: msg.from,
    mensajeId: msg.id ?? '',
    nombrePerfil: contacto?.profile?.name ?? '',
  }), pairedItem: { item: i } });
}
return out;

// El comercio no esta operativo (suspendido o dado de baja). Aplica tambien a
// NovuChat: si alguien suspende el tenant `novuchat`, este flujo deja de
// atender, igual que el de cualquier cliente. Se corta ANTES del agente, asi
// que no consume tokens.
//
// PROHIBIDO REVELAR EL MOTIVO: el texto es neutro y sale de la configuracion.
const cfg = $('Config del negocio').first().json;
const aviso = String(cfg.mensajeComercioSuspendido ?? '').trim()
  || 'En este momento no podemos atenderte por este medio. Gracias por escribirnos.';

return $input.all().map((it, i) => ({ json: { ...it.json,
  respuesta: aviso,
  comercioSuspendido: true,
}, pairedItem: { item: i } }));

// ESTADO DE LA CONVERSACION: decide que hace este turno, ANTES de llamar al
// modelo. Es donde viven la compuerta inicial, el fin del primer bloque y la
// idempotencia.
//
// EL TECHO DE COSTO LO DECIDE EL SERVIDOR, no este nodo. `Config del negocio`
// trae `atencionEstado` -- normal, operador o bloqueado --, calculado con los
// umbrales de la cuenta del tenant (`atencion.ts`), igual que en los flujos A
// y B. Aca solo se obedece: en operador o bloqueado el agente no se alcanza.
//
// LO QUE SI SE GUARDA ACA, en los datos estaticos del flujo, por telefono: la
// etapa (bienvenida, cliente actual, cliente nuevo, cerrado), los datos del
// prospecto y los ids de mensaje ya procesados. No es informacion que el
// servidor tenga, y no se factura sobre ella. n8n guarda los datos estaticos
// solo en ejecuciones de PRODUCCION (el disparador publicado); probando desde
// el editor, cada ejecucion arranca de cero.
//
// UNA VENTANA NUEVA ES UNA CONVERSACION NUEVA. A las 24 horas el servidor abre
// otra ventana y factura otra conversacion: lo que este nodo recuerda del turno
// -- la etapa, la bienvenida y el aviso -- vence con ella. Antes solo se
// reiniciaba el contador, y un prospecto que volvia un mes despues no recibia
// la bienvenida, no veia el boton y no generaba un aviso nuevo (primera prueba
// con telefonos reales, 15/09/2026). LO QUE NO VENCE son los datos del
// prospecto (`lead`): el prompt los ve en «Datos ya registrados» y no le vuelve
// a preguntar lo que ya dijo.
//
// QUE DECIDE (campo `accion`):
//   uso_extendido   el servidor dice operador o bloqueado: mensaje fijo o
//                   silencio, y aviso a una persona. Sin modelo.
//   bienvenida      primer «hola» suelto: los dos botones, sin modelo. Queda
//                   marcada solo si Meta acepta el envio (`Confirmar envio`).
//   cliente_actual  eligio «Soy cliente actual» (o lo escribio): un mensaje
//                   con la consola y un boton a una persona, sin modelo.
//   asesor          toco «Hablar con un asesor» (o lo escribio): el traspaso,
//                   sin modelo, con los datos que haya aunque falten. `avisado`
//                   tampoco se marca aca: lo marca `Confirmar envio` si Meta
//                   acepto la plantilla.
//   agente          todo lo demas.
// Y NO DEVUELVE NADA -- el flujo termina sin responder -- en dos casos:
//   - el mismo `mensajeId` ya se proceso: Meta reenvia el evento si n8n tarda,
//     y sin esto el prospecto recibe dos respuestas (Analisis/25 §3.3);
//   - el telefono esta bloqueado y ya se aviso: no hay nada que enviar.
//
// EL RUBRO NO SE ELIGE POR NUMERO (Andres, 22/09/2026). Hasta esa fecha la
// marca [RUBROS] mostraba una lista numerada y aca se resolvia el «3» del
// cliente antes de llamar al modelo. Los rubros pasaron a ser AREAS DE
// REFERENCIA, en linea y sin numerar -- ver `Procesar respuesta` --, asi que
// no hay ningun numero que resolver: un «2» suelto vuelve a ser un mensaje
// mas. El rubro lo registra el modelo en [LEAD] con lo que diga el cliente,
// por la misma via por la que ya lo deducia del nombre de la empresa.
const VENTANA_MS = 24 * 60 * 60 * 1000;
const DEDUP_MS = 10 * 60 * 1000;
const OLVIDO_MS = 48 * 60 * 60 * 1000;
// Sin NIT: se dejo de pedir (decision de Andres del 15/09). `flujos` no se le
// pregunta al cliente: se deduce del rubro.
const OBLIGATORIOS = ['empresa', 'contacto', 'rubro'];

const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos ?? {};
sd.conversaciones = sd.conversaciones ?? {};
const ahora = Date.now();

// Limpieza: los ids se recuerdan 10 minutos; las conversaciones, 48 horas sin
// mensajes. Sin esto los datos estaticos crecen para siempre.
for (const [id, t] of Object.entries(sd.vistos)) {
  if (ahora - t > DEDUP_MS) delete sd.vistos[id];
}
for (const [tel, c] of Object.entries(sd.conversaciones)) {
  if (ahora - (c.ultimo ?? 0) > OLVIDO_MS) delete sd.conversaciones[tel];
}

const hora = new Date(ahora).toLocaleString('es-BO', {
  timeZone: 'America/La_Paz', weekday: 'long', day: 'numeric', month: 'long',
  year: 'numeric', hour: '2-digit', minute: '2-digit',
});

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const e = items[i].json;

  if (e.mensajeId && sd.vistos[e.mensajeId]) continue;   // reenvio de Meta
  if (e.mensajeId) sd.vistos[e.mensajeId] = ahora;

  const nueva = !sd.conversaciones[e.from];
  const c = sd.conversaciones[e.from] ?? {
    desde: ahora, respuestas: 0, etapa: '', bienvenida: false, avisado: false, lead: {},
  };
  c.lead = c.lead ?? {};
  // Un NIT guardado antes del cambio no sigue viajando.
  delete c.lead.nit;
  // Contador PROPIO solo como respaldo del fin del primer bloque, para cuando el
  // panel no contesta. Ventana fija de 24 horas, como la del servidor.
  //
  // Y con la ventana vence la conversacion entera: etapa, bienvenida y aviso
  // vuelven a cero, y el prospecto que regresa es recibido como la primera vez.
  // MENSAJES: +1 por cada ventana nueva en la que un conocido salude suelto (la
  // bienvenida); es el comportamiento buscado, y no se repite dentro de la
  // ventana. Los datos del prospecto (`lead`) se conservan.
  if (ahora - c.desde >= VENTANA_MS) {
    c.desde = ahora;
    c.respuestas = 0;
    c.etapa = '';
    c.bienvenida = false;
    c.avisado = false;
    delete c.avisoFalla;
  }
  c.ultimo = ahora;

  const estadoServidor = e.atencionEstado === 'operador' || e.atencionEstado === 'bloqueado'
    ? e.atencionEstado : 'normal';

  let accion;
  if (estadoServidor !== 'normal') {
    accion = 'uso_extendido';
  } else if (e.eleccion === 'asesor') {
    accion = 'asesor';
  } else if (e.eleccion === 'cliente_actual' && c.etapa !== 'cliente_actual') {
    accion = 'cliente_actual'; c.etapa = 'cliente_actual';
  } else if (e.eleccion === 'cliente_nuevo') {
    accion = 'agente'; if (c.etapa !== 'cerrado') c.etapa = 'cliente_nuevo';
  } else if (!c.etapa && e.esSaludo && !c.bienvenida) {
    // Un «hola» suelto: los botones. Una sola vez; si vuelve a saludar sin
    // elegir, sigue el asistente y no se le repiten los botones.
    // `c.bienvenida` NO se marca aca: la marca `Confirmar envio` cuando Meta
    // acepto el mensaje. Marcada antes de enviar, un envio fallido dejaba a
    // ese telefono sin botones para siempre (aceptacion del 15/09/2026).
    accion = 'bienvenida';
  } else {
    // Quien ya dijo lo que quiere -- «hola, cuanto cuesta» -- no tiene que
    // tocar ningun boton: pasa directo al asistente como cliente nuevo.
    accion = 'agente'; if (!c.etapa) c.etapa = 'cliente_nuevo';
  }

  // Bloqueado y ya avisado: no hay mensaje ni aviso que mandar.
  const avisaServidor = e.atencionAvisarRecepcion === 'operador' || e.atencionAvisarRecepcion === 'bloqueado';
  if (estadoServidor === 'bloqueado' && !avisaServidor) { sd.conversaciones[e.from] = c; continue; }

  // La respuesta que se va a enviar es la numero `siguiente` de la ventana. Se
  // toma el conteo del SERVIDOR cuando llego; el propio es el respaldo.
  const enviadas = typeof e.atencionRespuestas === 'number' ? e.atencionRespuestas : c.respuestas;
  const siguiente = enviadas + 1;
  if (estadoServidor !== 'bloqueado') c.respuestas = siguiente;
  sd.conversaciones[e.from] = c;

  const topeAviso = Number(e.topeAviso) || 25;
  const finBloque = accion === 'agente' && siguiente === topeAviso;
  const lead = c.lead;
  const faltan = OBLIGATORIOS.filter((k) => !lead[k]);
  const modo = c.etapa === 'cliente_actual' ? 'CLIENTE ACTUAL' : 'CLIENTE NUEVO';

  // EL MENSAJE DEL TURNO lleva todo lo que cambia entre un turno y otro -- la
  // hora, quien escribe, los datos ya registrados, el contador -- para que las
  // instrucciones del agente queden fijas y el proveedor pueda cachearlas.
  const mensajeDelTurno = [
    '[CONTEXTO DEL TURNO - no lo repitas al cliente]',
    'Fecha y hora en La Paz: ' + hora + '.',
    'Modo: ' + modo + '.',
    'Nombre de perfil de WhatsApp: ' + (e.nombrePerfil || 'sin nombre') + '.',
    'Datos ya registrados: ' + JSON.stringify(lead) + '. Faltan: ' + (faltan.join(', ') || 'ninguno') + '.',
    // EL RUBRO SE PIDE POR CODIGO, NO SOLO POR PROMPT. Medido el 22/09/2026
    // con `scripts/comparar-prompt.mjs` (30 corridas por version contra
    // gemini-3.5-flash-lite): sin esta linea el modelo pone la marca [RUBROS]
    // en el 83 % de los turnos; con ella, en el 93 %. Es el mismo
    // criterio del candado de las citas (CLAUDE.md): una instruccion del prompt
    // se ignora, una indicacion del turno no depende de su voluntad. Solo
    // cuando YA se sabe de que empresa se trata: antes de eso el paso que toca
    // es pedir el nombre y la empresa, no el rubro.
    (lead.empresa || lead.contacto) && !lead.rubro && modo === 'CLIENTE NUEVO'
      ? 'Ya sabes a qué empresa pertenece y NO sabes su rubro: en ESTE mensaje escribe la marca ' +
        '[RUBROS] en su propia línea y pídele que te cuente a qué se dedica su negocio.' : '',
    c.etapa === 'cerrado' && c.avisado === true
      ? 'Ya se avisó a un asesor: no vuelvas a pedir datos ni a ofrecer el asesor.' : '',
    c.etapa === 'cerrado' && c.avisado !== true
      ? 'Se cerró la conversación pero el aviso al asesor NO salió: no vuelvas a pedir datos, y ' +
        'ofrécele hablar con un asesor (el mensaje sale con el botón).' : '',
    e.anuncio && e.anuncio.titular ? 'Llegó desde un anuncio: «' + e.anuncio.titular + '».' : '',
    finBloque ? 'Esta es la respuesta ' + topeAviso + ' de la conversacion: responde y, en este mismo mensaje, ofrece hablar con un asesor (el mensaje sale con el botón).' : '',
    '[MENSAJE DEL CLIENTE]',
    String(e.userInput ?? ''),
  ].filter(Boolean).join('\n');

  out.push({ json: {
    ...e,
    accion,
    etapa: c.etapa,
    respuestasEnVentana: siguiente,
    finBloque,
    primeraVez: nueva,
    leadConocido: lead,
    mensajeDelTurno,
  }, pairedItem: { item: i } });
}
return out;

// BIENVENIDA: la compuerta inicial (guion de Silvana, paso 1). Dos BOTONES de
// respuesta y no una lista: dos opciones en una lista son dos toques, en
// botones uno, y cuestan lo mismo -- 1 mensaje --. Sin llamar al modelo.
//
// EL NOMBRE Y LOS EMOJIS SALEN DE LA CONSOLA. `nombreAsistente` (voz) puede
// venir vacio: entonces se presenta como «el asistente virtual de NovuChat».
// `nivelEmojis` gobierna los textos fijos, que el modelo no escribe:
// `ninguno` los quita todos, `pocos` deja el primero, `muchos` deja los del
// guion. Nunca hay un emoji dentro de un precio: aca no hay precios.
//
// Los titulos de boton tienen un maximo de 20 caracteres (Meta). Si Meta
// rechazara el interactivo, `Enviar texto de respaldo` manda `textoRespaldo`.
const EMOJI = /\p{Extended_Pictographic}\uFE0F?/gu;
function conEmojis(t, nivel) {
  if (nivel === 'muchos') return t;
  let quedo = false;
  return t.replace(EMOJI, (m) => {
    if (nivel !== 'ninguno' && !quedo) { quedo = true; return m; }
    return '';
  }).replace(/[ \t]{2,}/g, ' ').replace(/ +\n/g, '\n').trim();
}

return $input.all().map((it, i) => {
  const e = it.json;
  const negocio = e.nombreNegocio || 'NovuChat';
  const nombre = String(e.nombreAsistente || '').trim();
  const quien = nombre ? nombre + ', el asistente virtual de ' + negocio : 'el asistente virtual de ' + negocio;
  const cuerpo = conEmojis('¡Hola! 👋 Soy ' + quien + ', impulsado por Inteligencia Artificial. ' +
    'Qué gusto tenerte por aquí. Cuéntame, ¿ya eres parte de la familia ' + negocio +
    ' o eres un cliente nuevo buscando automatizar sus ventas? 🚀', e.nivelEmojis);
  return { json: { ...e,
    respuesta: cuerpo,
    cuerpoMeta: {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: e.from,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: cuerpo },
        footer: { text: (negocio + ' · asistentes de WhatsApp para negocios').slice(0, 60) },
        action: { buttons: [
          { type: 'reply', reply: { id: 'cliente_actual', title: 'Soy cliente actual' } },
          { type: 'reply', reply: { id: 'cliente_nuevo', title: 'Soy cliente nuevo' } },
        ] },
      },
    },
    textoRespaldo: cuerpo + '\n\nEscríbeme «soy cliente» o cuéntame qué necesitas.',
  }, pairedItem: { item: i } };
});

// CLIENTE ACTUAL: un mensaje con la consola y un boton a una persona, y fin.
// Sin llamar al modelo.
//
// NO LLEVA NINGUN CODIGO. La especificacion pedia «Ingresa a la Consola con el
// codigo XXXXX»; la consola no tiene codigo -- se entra con correo y
// contrasena -- y un codigo fijo que se le da a cualquiera que toque «Soy
// cliente actual» seria una filtracion por diseño. Decidido por Andres el
// 14/09/2026 (CLIENTES/NOVUCHAT/01-… §8).
//
// El boton `cta_url` abre el WhatsApp de una persona. El texto del boton tiene
// un maximo de 20 caracteres. Si no hay numero de recepcion, va solo el texto.
return $input.all().map((it, i) => {
  const e = it.json;
  let cuerpo = String(e.mensajeClienteActual || '').trim();
  const enlace = String(e.enlaceConsola || '').trim();
  const dominio = enlace.replace(/^https?:\/\//, '').replace(/\/.*$/, '');
  if (enlace && dominio && !cuerpo.includes(dominio)) cuerpo += '\n\n' + enlace;

  const recepcion = String(e.numeroRecepcion || '').replace(/\D/g, '');
  const url = recepcion
    ? 'https://wa.me/' + recepcion + '?text=' +
      encodeURIComponent('Hola, soy cliente de NovuChat y necesito ayuda con la consola.')
    : '';

  return { json: { ...e,
    respuesta: cuerpo,
    cuerpoMeta: url ? {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: e.from,
      type: 'interactive',
      interactive: {
        type: 'cta_url',
        body: { text: cuerpo },
        action: { name: 'cta_url', parameters: { display_text: 'Pedir ayuda', url } },
      },
    } : undefined,
    textoRespaldo: url ? cuerpo + '\n\nPara hablar con una persona: ' + url : cuerpo,
  }, pairedItem: { item: i } };
});

// USO EXTENDIDO: el servidor dice que este telefono paso el umbral de
// operador o el de bloqueo (`Analisis/27` §5, `atencion.ts`). Es el mismo
// mecanismo que obedecen los flujos A y B, con los umbrales de la cuenta del
// tenant (`cuenta/estado`: 50 y 100 por defecto). Cubre lo que la
// especificacion de Silvana llamaba «tope duro».
//
// NO SE LLAMA AL MODELO en ninguno de los dos casos: este nodo cuelga antes
// del agente.
//
//   operador  -> un mensaje fijo: una persona sigue la conversacion. Cuenta y
//                se factura como cualquier respuesta.
//   bloqueado -> no se responde nada al cliente.
//   En los dos, la PRIMERA vez que se entra al estado (el servidor lo marca en
//   `atencionAvisarRecepcion`) se avisa a una persona con la plantilla.
//
// El texto va con TUTEO, que es la voz de NovuChat. El del servidor
// (`MENSAJE_USO_EXTENDIDO`) es neutro y de usted, para los comercios.
const FIJO = 'Gracias por tu paciencia. Para atenderte mejor, una persona del equipo de ' +
  'NovuChat va a seguir esta conversación en breve, por este mismo WhatsApp.';

return $input.all().map((it, i) => {
  const e = it.json;
  const bloqueado = e.atencionEstado === 'bloqueado';
  const avisar = e.atencionAvisarRecepcion === 'operador' || e.atencionAvisarRecepcion === 'bloqueado';
  return { json: { ...e,
    responder: !bloqueado,
    respuesta: bloqueado ? '' : FIJO,
    avisar,
    estadoAviso: bloqueado ? 'llegó al límite de respuestas del día' : 'pasó a atención de una persona',
    estadoLead: bloqueado ? 'bloqueado' : 'operador',
    guardarLead: avisar,
  }, pairedItem: { item: i } };
});

// TRASPASO A UN ASESOR (guion de Silvana, paso 5): el cliente toco «Hablar con
// un asesor» -- o lo escribio --. SIN MODELO, como la rama del cliente actual:
// el texto es fijo y la decision tambien.
//
// HACE TRES COSAS:
//  1. Le dice al cliente que sus datos pasaron al equipo y cuando le escriben:
//     «en horario de atencion (…)» si la consola tiene horario, «lo antes
//     posible» si no lo tiene. Nunca un horario de respaldo que nadie cumple.
//     Y EL MENSAJE SALE CON EL BOTON `cta_url` AL WHATSAPP DE UNA PERSONA
//     (`numeroRecepcion`, el mismo que usa `Cliente actual`). Hasta el
//     22/09/2026 este mensaje solo prometia que un especialista escribiria:
//     el prospecto quedaba esperando, sin ninguna forma de escribir el. La
//     politica de NovuChat (CLAUDE.md, 21/09/2026) es que pasar con una
//     persona es SIEMPRE el aviso interno MAS el boton para escribirle
//     directo; sin el numero configurado no hay boton, y entonces el texto
//     tampoco invita a escribir. El boton VIAJA DENTRO DEL MISMO MENSAJE: no
//     cuesta un mensaje mas.
//  2. Avisa a recepcion con la plantilla, UNA vez por conversacion y con lo
//     que haya de los datos aunque falten: quien pide una persona no tiene que
//     completar un formulario antes. `Salida` no le avisa al propio numero de
//     recepcion (la misma regla del Demo B, #68). «Una vez» se cuenta sobre los
//     avisos que META ACEPTO (`c.avisado`, que escribe `Confirmar envio`): si la
//     plantilla fue rechazada -- estaba en revision el 15/09/2026 --, el proximo
//     toque vuelve a intentarlo. Un mensaje que Meta rechaza no se cobra.
//  3. Guarda el prospecto y deja la etapa en `cerrado`: el asistente sigue
//     respondiendo dudas, pero ya no pide datos.
//
// MENSAJES: 1 al cliente (con el boton adentro), y 1 plantilla utility la
// primera vez. El cambio del 22/09 no agrega ninguno.
const EMOJI = /\p{Extended_Pictographic}\uFE0F?/gu;
function conEmojis(t, nivel) {
  if (nivel === 'muchos') return t;
  let quedo = false;
  return t.replace(EMOJI, (m) => {
    if (nivel !== 'ninguno' && !quedo) { quedo = true; return m; }
    return '';
  }).replace(/[ \t]{2,}/g, ' ').replace(/ +\n/g, '\n').trim();
}

const sd = $getWorkflowStaticData('global');
sd.conversaciones = sd.conversaciones ?? {};

return $input.all().map((it, i) => {
  const e = it.json;
  const negocio = e.nombreNegocio || 'NovuChat';
  const cuando = String(e.fraseContacto || '').trim() || 'lo antes posible';
  // El numero de una persona. Sin el no hay boton, y el texto no promete nada
  // que no se pueda cumplir desde este mismo mensaje.
  const recepcion = String(e.numeroRecepcion || '').replace(/\D/g, '');
  const url = recepcion
    ? 'https://wa.me/' + recepcion + '?text=' +
      encodeURIComponent('Hola, escribo desde el WhatsApp de ' + negocio + '. Quiero hablar con un asesor.')
    : '';

  const texto = conEmojis('¡Anotado! 📋 Ya le pasé tus datos a nuestro equipo. Un especialista de ' +
    negocio + ' te escribirá a este mismo número ' + cuando +
    (url ? ', y si prefieres no esperar, toca el botón y escríbele ahora mismo.' : '.') +
    ' ¡Que tengas un excelente día! ✨',
    e.nivelEmojis);

  const c = sd.conversaciones[e.from];
  const lead = (c && c.lead) || e.leadConocido || {};
  const avisar = !(c && c.avisado);
  if (c && c.etapa !== 'cliente_actual') c.etapa = 'cerrado';

  return { json: { ...e,
    respuesta: texto,
    // El boton `cta_url` abre el WhatsApp de una persona. El texto del boton
    // tiene un maximo de 20 caracteres (Meta). Si `Salida` no puede mandar el
    // interactivo, `textoRespaldo` lleva el enlace adentro.
    cuerpoMeta: url ? {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: e.from,
      type: 'interactive',
      interactive: {
        type: 'cta_url',
        body: { text: texto },
        action: { name: 'cta_url', parameters: { display_text: 'Escribir ahora', url } },
      },
    } : undefined,
    textoRespaldo: url ? texto + '\n\nPara escribirle a una persona: ' + url : texto,
    lead,
    avisar,
    estadoAviso: e.etapa === 'cliente_actual' ? 'pidió hablar con una persona' : 'pidió hablar con un asesor',
    guardarLead: true,
    estadoLead: 'cerrado',
  }, pairedItem: { item: i } };
});

// PROCESAR RESPUESTA: separa las marcas del agente, arma POR CODIGO lo que no
// puede depender del modelo -- la lista de rubros y los planes con sus
// precios -- y aplica la prohibicion 4 (el agente no niega ser una IA). Un
// modelo puede omitir una frase de las instrucciones; lo que no se negocia no
// depende de su voluntad.
//
// LAS MARCAS, que el cliente nunca ve:
//   [LEAD]{json}[/LEAD]  los datos del prospecto que el cliente dio o corrigio
//                        en este turno. Una sola llamada al modelo por turno:
//                        la extraccion viaja en la misma respuesta.
//   [RUBROS]             se reemplaza por las AREAS DE REFERENCIA de la
//                        consola, en linea y SIN NUMERAR, con la frase que
//                        aclara que no son las unicas. Ver mas abajo.
//   [PLANES]             se reemplaza por el bloque de planes y cargos unicos,
//                        con los precios EXACTOS de la consola. Si la consola
//                        manda los planes en archivo (mas de 5), el archivo va
//                        de encabezado del mensaje. Sin planes cargados no hay
//                        precios: se ofrece al asesor. El mensaje sale con el
//                        boton «Hablar con un asesor».
//   [CIERRE]             el cliente pidio por escrito que lo contacten y ya
//                        estan los datos obligatorios: se avisa a una persona.
//
// UN [CIERRE] SIN LOS DATOS NO CIERRA. El modelo puede apurarse; el aviso
// interno cuesta un mensaje utility y le quita tiempo a una persona, asi que
// se exige que empresa, contacto y rubro esten de verdad registrados. En su
// lugar, la respuesta sale con el boton: tocarlo pasa al asesor con lo que haya.
// La excepcion es el cliente actual que pide una persona: ahi no hay datos de
// prospecto que exigir.
//
// QUE EL BOTON SOBREVIVA AL LIMITE DE META. El cuerpo de un mensaje con botones
// admite hasta `limiteInteractivo` caracteres (1024, `Config base`). Pasarse no
// da error: `Salida` baja el mensaje a texto y el cliente se queda SIN la unica
// salida hacia una persona. Paso el 15/09/2026, con los planes en 1411
// caracteres, y la ejecucion figuro «success». Antes de resignar el boton se
// compacta, en este orden y deteniendose apenas entra:
//   1. el texto del modelo -- el envoltorio -- recortado por palabras, con «…»
//      al final (`texto_recortado`), y NUNCA por debajo de `PISO_TEXTO`;
//   2. solo si ni asi entra, el bloque de planes sin lo que incluye cada plan
//      ni el detalle de cada cargo -- nombre, precio y periodo --
//      (`planes_compactados`). Con el bloque resumido el texto se vuelve a
//      recortar desde el original, para no quitarle mas de lo necesario;
//   3. si ni asi entra, el mensaje sale entero como texto y sin boton -- lo hace
//      `Salida`, que lo anota con `boton_perdido_por_largo` --. Ahi no se
//      recorta nada: como texto caben 4096 y el boton ya esta perdido.
// LOS PRECIOS NO SE RECORTAN NUNCA: son lo que el cliente compara.
//
// EL ORDEN SE INVIRTIO el 15/09/2026 (ejecucion 2536). Estaba al reves --
// primero el bloque -- y con 380 caracteres del modelo y el bloque en 650
// (1030: SEIS caracteres de mas) el cliente recibio «Impulso (USD 25/mes).
// Crecimiento (USD 50/mes). Pro (USD 90/mes).», sin las conversaciones
// incluidas ni lo que trae cada plan, que es justo lo que se compara al elegir.
// El aviso quedo anotado, asi que el mecanismo funcionaba: lo que estaba mal
// era el orden. Lo que escribio el modelo es el envoltorio y se pierde primero;
// el precio Y EL DETALLE de cada plan son lo ultimo.
// MENSAJES POR TURNO: los mismos. Compactar no agrega ni quita un mensaje.
//
// EL BOTON «Hablar con un asesor» (respuesta, id `asesor`) va con los planes, al
// terminar el primer bloque y en un cierre sin datos. Reemplaza al enlace a
// wa.me de antes: tocarlo dispara `Traspaso a un asesor`, sin modelo. En el
// cierre completo NO va: la persona ya fue avisada y el boton solo invitaria a
// un mensaje pagado que repite el traspaso.
//
// PERO UN CIERRE SIN AVISO NO DEJA AL PROSPECTO SIN SALIDA. «Ya fue avisada»
// vale solo si Meta acepto la plantilla, y eso lo dice `c.avisado`, que escribe
// `Confirmar envio`. El 15/09/2026 la plantilla estaba en revision, Meta la
// rechazo (132001) y los cuatro telefonos que probaron quedaron cerrados, sin
// boton y sin que nadie los llamara. Mientras `avisado` sea falso, la respuesta
// de una conversacion cerrada sigue saliendo con el boton. NO CUESTA UN MENSAJE
// MAS: el boton viaja dentro del mismo.
const entradas = $('Estado de la conversación').all();
const sd = $getWorkflowStaticData('global');
sd.conversaciones = sd.conversaciones ?? {};

const NIEGA_IA = /(no\s+soy\s+(un[ao]?\s+)?(bot|robot|m[aá]quina|programa|inteligencia\s+artificial|\bia\b|asistente\s+virtual|autom[aá]tic[ao])|soy\s+(un[ao]?\s+)?(persona|humano|humana|ser\s+humano)|habl(as|[aá]s|a)\s+con\s+(un[ao]?\s+)?(persona|humano|humana))/i;
// Sin NIT desde el 15/09. `flujos` no lo pide el modelo: se deduce del rubro,
// pero se acepta si lo manda.
const CAMPOS = ['empresa', 'contacto', 'rubro', 'personalizacion', 'consulta', 'flujos'];
const OBLIGATORIOS = ['empresa', 'contacto', 'rubro'];
// UN DATO DE RELLENO NO ES UN DATO. El 15/09 el modelo marco rubro «Pendiente»
// sin que el cliente dijera nada: contaba como registrado, y con los otros tres
// el cierre avisaba a un asesor por un prospecto a medias.
const RELLENO = /^(pendiente|por (definir|confirmar)|a definir|desconocid[oa]|no (especificad[oa]|indicad[oa]|informad[oa]|sabe|lo sabe|dijo)|sin (dato|datos|definir|especificar)|n\/?a|ninguno|null|undefined|-+|\?+|…|\.{3})$/i;

const BOTON_ASESOR = { type: 'reply', reply: { id: 'asesor', title: 'Hablar con un asesor' } };
const PIDE_ASESOR = 'Si quieres hablar con un asesor, escríbeme «asesor».';
const SUFIJO = { mes: '/mes', anio: '/año', unico: ', pago único' };
const monto = (n) => Number.isInteger(n) ? String(n) : n.toFixed(2).replace('.', ',');
const punto = (t) => /[.!?…]$/.test(t) ? t : t + '.';
const norm = (t) => String(t ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

function leerLead(bruto) {
  const m = bruto.match(/\[LEAD\]([\s\S]*?)\[\/LEAD\]/i);
  if (!m) return { lead: {}, invalido: false };
  try {
    const j = JSON.parse(m[1].trim());
    const lead = {};
    for (const k of CAMPOS) {
      let v = j?.[k];
      if (Array.isArray(v)) v = v.map(String).join(', ');
      if (v === undefined || v === null) continue;
      v = String(v).replace(/\s+/g, ' ').trim().slice(0, 300);
      if (v && !RELLENO.test(v)) lead[k] = v;
    }
    return { lead, invalido: false };
  } catch {
    return { lead: {}, invalido: true };
  }
}

// El bloque de planes, armado con los precios de la consola. Formato del guion:
// «Nombre (USD 25/mes): Hasta 100 conversaciones.»
// COMPACTO: solo nombre, precio y periodo (y «desde» donde corresponde). Es lo
// que sale cuando el mensaje con boton no entra en el limite: se pierde lo que
// incluye cada plan, nunca un precio.
function bloquePlanes(ent, compacto) {
  const planes = Array.isArray(ent.planes) ? ent.planes : [];
  const cargos = Array.isArray(ent.cargosUnicos) ? ent.cargosUnicos : [];
  if (!planes.length) return '';
  const lineas = ['*Planes*'];
  for (const p of planes) {
    lineas.push(p.nombre + ' (USD ' + monto(p.precioUsd) + (SUFIJO[p.periodo] ?? '') + ')' +
      (!compacto && p.incluye ? ': ' + punto(p.incluye) : '.'));
  }
  if (cargos.length) {
    lineas.push('', '*Cargos únicos*');
    for (const c of cargos) {
      lineas.push(c.nombre + ' (pago único): ' + (c.desde ? 'desde ' : '') + 'USD ' + monto(c.precioUsd) +
        (!compacto && c.detalle ? '. ' + punto(c.detalle) : '.'));
    }
  }
  lineas.push('', 'Precios en dólares; se cobran en bolivianos al tipo de cambio oficial del BCB.');
  return lineas.join('\n');
}

// El texto del turno: el del modelo -- con la marca de los planes -- y el bloque
// que le toca. El mensaje de los planes termina siempre con la pregunta por el
// especialista, la haya escrito el modelo o no. Es una funcion y no dos lineas
// sueltas porque el texto se vuelve a armar con el bloque compacto o con el
// texto recortado cuando no entra en el limite.
const PREGUNTA_ESPECIALISTA = '¿Te gustaría hablar con un especialista?';
function armar(conMarca, bloque) {
  if (!bloque) return conMarca.replace(/\u0002/g, '').replace(/\n{3,}/g, '\n\n').trim();
  let t = conMarca.replace('\u0002', '\n' + bloque + '\n').replace(/\u0002/g, '');
  const cola = t.slice(t.lastIndexOf(bloque) + bloque.length);
  if (!/\?/.test(cola)) t = t.trimEnd() + '\n\n' + PREGUNTA_ESPECIALISTA;
  return t.replace(/\n{3,}/g, '\n\n').trim();
}

// Recorta por palabras y cierra con «…»: una palabra cortada por la mitad se
// lee como un error del asistente.
function recortar(t, max) {
  if (t.length <= max) return t;
  if (max < 2) return '';
  const corte = t.slice(0, max - 1);
  const hasta = corte.search(/\s+\S*$/);
  return (hasta > 0 ? corte.slice(0, hasta) : corte).trimEnd().replace(/[,;:.\-]+$/, '') + '…';
}

// PISO DEL TEXTO DEL MODELO. Por debajo de estos caracteres el envoltorio deja
// de ser un mensaje: 150 son dos oraciones cortas -- la frase que presenta el
// bloque y la pregunta del final --, que es el minimo para que los precios
// lleguen dentro de algo dicho por alguien. Si con el texto en el piso el
// mensaje sigue sin entrar, NO se recorta mas: se resume el bloque, que aun
// resumido conserva todos los precios.
const PISO_TEXTO = 150;

// Arma el texto contra un bloque dado y, si no entra en el limite, recorta solo
// el texto del modelo -- lo de antes y lo de despues del bloque --, por
// palabras y empezando por la porcion mas larga (casi siempre el enganche que
// va antes de los precios), para no perder entera la frase del final. El bloque
// NO se toca. Nunca baja del piso: lo que falte lo resuelve quien llama,
// resumiendo el bloque.
function ajustar(conMarca, bloque, limite, piso) {
  const entero = armar(conMarca, bloque);
  if (entero.length <= limite) return { texto: entero, recortado: false };
  const k = conMarca.indexOf('\u0002');
  let pre = k >= 0 ? conMarca.slice(0, k) : conMarca;
  let post = k >= 0 ? conMarca.slice(k + 1) : '';
  const rehacer = () => armar(pre + '\u0002' + post, bloque);
  // Lo que se puede quitar sin bajar del piso.
  let margen = Math.max(0, pre.length + post.length - piso);
  for (const cual of pre.length >= post.length ? ['pre', 'post'] : ['post', 'pre']) {
    const sobra = Math.min(rehacer().length - limite, margen);
    if (sobra <= 0) break;
    if (cual === 'pre' && pre.trim()) {
      const antes = pre.length; pre = recortar(pre, pre.length - sobra); margen -= antes - pre.length;
    }
    if (cual === 'post' && post.trim()) {
      const antes = post.length; post = recortar(post, post.length - sobra); margen -= antes - post.length;
    }
  }
  const texto = rehacer();
  return { texto, recortado: texto.length < entero.length };
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  // Emparejamiento por indice: nunca .first(), que le pondria el telefono del
  // primer mensaje a todos los items si llegaran dos a la vez.
  const ent = (entradas[i] ?? entradas[entradas.length - 1]).json;
  const bruto = String(items[i].json.output ?? items[i].json.text ?? '').trim();

  const { lead, invalido } = leerLead(bruto);
  const pideCierre = /\[CIERRE\]/i.test(bruto);
  const conRubros = /\[RUBROS\]/i.test(bruto);
  const conPlanes = /\[PLANES\]/i.test(bruto);
  const rubros = Array.isArray(ent.rubros) ? ent.rubros : [];
  const hayPlanes = Array.isArray(ent.planes) && ent.planes.length > 0;
  const archivo = hayPlanes && ent.planesEnArchivo === true && ent.archivoPlanes && ent.archivoPlanes.url
    ? ent.archivoPlanes : null;

  const avisos = [];
  if (invalido) avisos.push('lead_invalido');

  // Lo que el modelo escribe no lleva la oferta: las marcas se reemplazan
  // DESPUES de revisar su texto, para que la correccion de la prohibicion 4 no
  // toque un precio.
  let texto = bruto
    .replace(/\[LEAD\][\s\S]*?\[\/LEAD\]/gi, '')
    .replace(/\[\/?LEAD\]/gi, '')
    .replace(/\[CIERRE\]/gi, '')
    .replace(/\[RUBROS\]/gi, '\u0001')
    .replace(/\[PLANES\]/gi, '\u0002')
    .replace(/\[[A-ZÁÉÍÓÚÑ_ ]{3,30}\]/g, '')
    .trim();

  // --- Prohibicion 4: el agente no niega ser una IA ---------------------
  if (NIEGA_IA.test(texto)) {
    texto = texto.replace(new RegExp(NIEGA_IA.source, 'gi'), 'sí, soy un asistente virtual con inteligencia artificial');
    avisos.push('correccion_ia');
  }

  // --- Un precio que el modelo escribio por su cuenta ---------------------
  // Se deja como esta (quitarlo podria dejar una frase rota), pero se anota si
  // no coincide con ningun precio de la consola: es la señal de que el modelo
  // tomo un precio del corpus o lo invento.
  const permitidos = new Set([...(ent.planes ?? []), ...(ent.cargosUnicos ?? [])].map((p) => monto(p.precioUsd)));
  for (const m of texto.matchAll(/(?:USD|US\$|\$us|\$)\s?(\d+(?:[.,]\d{1,2})?)/gi)) {
    if (!permitidos.has(m[1].replace('.', ','))) { avisos.push('precio_fuera_de_la_consola'); break; }
  }

  // --- Datos del prospecto, combinados (se necesitan ya, ver la red de abajo)
  const c = sd.conversaciones[ent.from];
  const previo = c?.lead ?? ent.leadConocido ?? {};
  const combinado = { ...previo, ...lead };
  delete combinado.nit;

  // --- [RUBROS]: areas de referencia, NO un menu de servicios --------------
  // Decision de Andres del 22/09/2026. El 22/09 el asistente le mostro a una
  // cafeteria cinco rubros numerados -- «1. Salud y Belleza… 5. Otro / a
  // medida» -- y le pidio que contestara con el numero: el prospecto lee ahi
  // el catalogo completo de lo que NovuChat sabe hacer, y quien no encaja se
  // va. NovuChat atiende negocios de cualquier rubro; la lista sirve para que
  // el cliente se ubique, no para que elija.
  //
  // POR ESO: en linea y sin numerar, con «algunas» adelante y la salida
  // explicita al final. El rubro «a medida» NO se enumera -- no es un area,
  // es la ausencia de una -- y su lugar lo ocupa esa ultima frase. El rubro
  // lo registra el modelo con lo que diga el cliente, como ya hace cuando lo
  // deduce del nombre de la empresa: no hay ningun numero que contar.
  const esAMedida = (r) => /medida|^otro/i.test(String(r.id) + ' ' + String(r.nombre));
  const areas = rubros.filter((r) => !esAMedida(r)).map((r) => r.nombre);
  // Separadas por comas y sin «y» final: los nombres de rubro ya traen su
  // propia «y» («Salud y Belleza», «Comercio y Retail») y encadenarlas se
  // traba al leer.
  const listaRubros = areas.length
    ? 'Por darte una referencia, algunas áreas en las que ya trabajamos: ' + areas.join(', ') +
      '. Si lo tuyo no está en esa lista, cuéntamelo igual: trabajamos con negocios de todo tipo.'
    : '';
  texto = texto.replace(/\u0001/g, listaRubros ? '\n' + listaRubros + '\n' : '');

  // LA RED: SI EL MODELO NO PUSO LA MARCA, LA PONE EL CODIGO. Medido el
  // 22/09/2026 (`scripts/comparar-prompt.mjs`, 30 corridas por version): el
  // modelo pone [RUBROS] en el 83 % de los turnos por su cuenta, y en el 93 %
  // con la indicacion del turno que agrega `Estado de la conversacion`. Ese 7 %
  // restante es un prospecto que nunca ve a que se dedica NovuChat y al que hay
  // que volver a preguntarle -- un mensaje mas, pagado --. Asi que cuando YA se
  // sabe la empresa, NO se sabe el rubro y el modelo no puso la marca, la
  // referencia se agrega al final del mismo mensaje. NO CUESTA UN MENSAJE MAS.
  // Es el mismo criterio del boton del asesor unas lineas mas abajo: lo que no
  // puede depender de la voluntad del modelo, no depende.
  const faltaRubro = !conRubros && listaRubros && !combinado.rubro
    && (combinado.empresa || combinado.contacto)
    && ent.etapa !== 'cerrado' && ent.etapa !== 'cliente_actual';
  if (faltaRubro) {
    texto = texto.trimEnd() + '\n\n' + listaRubros;
    avisos.push('rubros_agregados_por_codigo');
  }

  // --- [PLANES]: el bloque armado por codigo --------------------------------
  // `conMarca` -- lo que escribio el modelo, con la marca de los planes -- y
  // `bloqueLargo` se guardan: con ellos se vuelve a armar el texto si hay que
  // compactarlo para que el boton entre (ver el encabezado).
  const conMarca = texto;
  const bloqueLargo = !conPlanes ? ''
    : !hayPlanes ? 'Los precios te los confirma un asesor de ' + (ent.nombreNegocio || 'NovuChat') + '.'
    : archivo ? 'Te comparto los planes y sus precios en el archivo de arriba.'
    : bloquePlanes(ent, false);
  texto = armar(conMarca, bloqueLargo);

  if (!texto) {
    texto = 'Disculpa, no pude generar la respuesta. ¿Me lo repites?';
    avisos.push('respuesta_vacia');
  }

  // --- Datos del prospecto: se acumulan en la conversacion ----------------
  // `combinado` se armo arriba, antes del reemplazo de [RUBROS].
  // `flujos` se deduce del rubro, cuando el rubro es uno de la lista.
  if (combinado.rubro && (lead.rubro || !combinado.flujos)) {
    const r = rubros.find((x) => norm(x.nombre) === norm(combinado.rubro) || norm(x.id) === norm(combinado.rubro));
    if (r && r.flujoSugerido) combinado.flujos = r.flujoSugerido;
  }
  const cambios = Object.keys(combinado).filter((k) => previo[k] !== combinado[k]);
  const completo = OBLIGATORIOS.every((k) => combinado[k]);
  const cierre = pideCierre && (completo || ent.etapa === 'cliente_actual');
  if (pideCierre && !cierre) avisos.push('cierre_sin_datos');
  const avisar = cierre && !(c?.avisado);

  if (c) {
    c.lead = combinado;
    // `c.avisado` NO se marca aca: lo marca `Confirmar envio` cuando Meta acepto
    // la plantilla. Marcado al decidirlo, un aviso rechazado dejaba al prospecto
    // por avisado y sin boton para siempre.
    if (cierre && c.etapa !== 'cliente_actual') c.etapa = 'cerrado';
    // `esperaRubro` se retiro el 22/09/2026 junto con la lista numerada: sin
    // numeros a la vista, un «2» del cliente es un mensaje mas, no un rubro.
  }

  // --- El boton «Hablar con un asesor» -------------------------------------
  const yaCerrado = cierre || c?.etapa === 'cerrado' || ent.etapa === 'cerrado';
  // Cerrado, pero con el aviso sin confirmar y sin uno saliendo en este turno:
  // la salida hacia una persona se sigue ofreciendo en cada respuesta.
  const cerradoSinAviso = !avisar && !!c && c.etapa === 'cerrado' && c.avisado !== true;
  // SOLO SE OFRECE LO QUE SE CUMPLE (politica de NovuChat, 21/09/2026). Si el
  // texto remite a un asesor o promete que alguien le va a responder, y en este
  // turno no sale el aviso a una persona, el mensaje lleva el boton: es la unica
  // forma de que esa promesa se cumpla. Una pregunta no promete nada.
  const PROMESA = /(consult|averigu|pregunt|verific|revis|coordin)[a-záéíóúñ]*\s+(lo\s+|eso\s+)?(con|a)\s+(recepci|la\s+cl[ií]nica|el\s+equipo|el\s+personal|(el|la)\s+(doctor|doctora|dr|dra)(?![a-záéíóúñ])|administraci|caja|alguien|una\s+persona|la\s+empresa|el\s+negocio|mis\s+compa)|(te|le)\s+(avis|escrib|llam|contact|confirm|mand|env[ií]|respond)[a-záéíóúñ]*\s+(luego|despu[eé]s|m[aá]s\s+tarde|ma[ñn]ana|en\s+cuanto|apenas|pronto|en\s+un\s+rato|en\s+breve|a\s+la\s+brevedad)|(te|le)\s+(avisar|escribir|llamar|contactar|confirmar|responder)([eé]|[aá]n?)(?![a-záéíóúñ])|voy\s+a\s+(consultar|averiguar|preguntar|avisar|escribir|llamar|contactar|confirmar)/i;
  const REMITE_ASESOR = /(asesor|especialista|una\s+persona\s+del\s+equipo)[^.!?\n]{0,40}(confirm|respond|escrib|contact|llam|avis|ayud|explic|cotiz)|(te|le)\s+(paso|pongo|comunico)\s+con/i;
  const prometeSinAviso = !avisar && texto.split(/(?<=[.!?…])\s+|\n+/)
    .some((o) => o.trim() && !/\?\s*$/.test(o.trim()) && (PROMESA.test(o) || REMITE_ASESOR.test(o)));
  if (prometeSinAviso) avisos.push('promesa_con_boton_asesor');
  const conBoton = cerradoSinAviso || (prometeSinAviso && !(c && c.avisado === true))
    || (!yaCerrado && (conPlanes || ent.finBloque === true || (pideCierre && !cierre)));

  // --- Que el boton sobreviva al limite de Meta ----------------------------
  // Ver el encabezado: primero el texto del modelo recortado, despues -- solo
  // si ni asi entra -- el bloque de planes resumido, y recien entonces se
  // resigna el boton (en `Salida`).
  const limite = Number(ent.limiteInteractivo) || 0;
  if (conBoton && limite > 0 && texto.length > limite) {
    // 1. El envoltorio: lo que escribio el modelo, por palabras y sin bajar del
    //    piso. Los precios y el detalle de cada plan quedan intactos.
    let pasos = [];
    let intento = ajustar(conMarca, bloqueLargo, limite, PISO_TEXTO);
    if (intento.recortado) pasos.push('texto_recortado');
    // 2. Recien ahora los planes, sin lo que incluye cada uno ni el detalle de
    //    cada cargo. Solo cuando el bloque ES la lista: con los planes en
    //    archivo o sin planes cargados, el bloque es una frase y no hay nada
    //    que resumir. Con el bloque corto el texto se recorta DESDE EL
    //    ORIGINAL: lo que el resumen libera se lo devuelve al modelo.
    const compacto = (hayPlanes && !archivo) ? bloquePlanes(ent, true) : '';
    if (intento.texto.length > limite && compacto && compacto.length < bloqueLargo.length) {
      intento = ajustar(conMarca, compacto, limite, PISO_TEXTO);
      pasos = intento.recortado ? ['texto_recortado', 'planes_compactados'] : ['planes_compactados'];
    }
    // 3. Si entra, se manda ajustado, y los avisos van EN EL ORDEN EN QUE SE
    //    APLICARON. Si no entra ni asi, se manda el texto ENTERO: el boton ya
    //    esta perdido y recortar solo le quitaria informacion al cliente.
    //    `Salida` lo baja a texto y lo anota.
    if (intento.texto.length <= limite) {
      texto = intento.texto;
      for (const a of pasos) avisos.push(a);
    }
  }

  const encabezado = conBoton && conPlanes && archivo
    ? (archivo.tipo === 'imagen'
      ? { type: 'image', image: { link: archivo.url } }
      : { type: 'document', document: { link: archivo.url, filename: archivo.nombreArchivo || 'Planes.pdf' } })
    : null;

  out.push({ json: { ...ent,
    respuesta: texto,
    cuerpoMeta: conBoton ? {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: ent.from,
      type: 'interactive',
      interactive: {
        type: 'button',
        ...(encabezado ? { header: encabezado } : {}),
        body: { text: texto },
        action: { buttons: [BOTON_ASESOR] },
      },
    } : undefined,
    // Si Meta rechaza el interactivo, el texto lleva el enlace del archivo y la
    // forma de pedir el asesor sin boton (`Normalizar entrada` lo reconoce).
    textoRespaldo: conBoton
      ? texto + (encabezado ? '\n\nPlanes: ' + archivo.url : '') + '\n\n' + PIDE_ASESOR
      : texto,
    lead: combinado,
    guardarLead: cambios.length > 0 || ent.primeraVez === true || avisar,
    estadoLead: cierre ? 'cerrado' : 'en_conversacion',
    avisar,
    estadoAviso: ent.etapa === 'cliente_actual' ? 'pidió hablar con una persona' : 'datos completos',
    avisos,
  }, pairedItem: { item: i } });
}
return out;

// SALIDA: la ultima compuerta. TODO lo que sale al cliente pasa por aca, venga
// de la bienvenida, del cliente actual, del traspaso a un asesor, del corte, del
// aviso de comercio no operativo o del agente. Arma tres cuerpos listos para enviar:
//
//   cuerpoMeta      el mensaje al cliente (interactivo o texto)
//   cuerpoRespaldo  el mismo en texto plano, por si Meta rechaza el interactivo
//   cuerpoAviso     la plantilla del aviso interno, si corresponde
//   cuerpoCrm       el registro del prospecto, si hay algo nuevo que guardar
//
// MENSAJES POR TURNO: UNO al cliente (o su respaldo si el primero fallo,
// nunca los dos), salvo con el telefono BLOQUEADO por el servidor, que no
// recibe nada (`responder: false`). El aviso interno es una plantilla utility
// aparte: +1 por prospecto que pasa a un asesor -- el boton o un cierre --, una
// vez por conversacion, y +1 por cada umbral que el servidor marca.
//
// Que el mensaje SALIO no lo decide este nodo: lo decide `Confirmar envio`, al
// final, con lo que contesto Meta. Solo eso se reporta y se da por hecho.
// El largo del cuerpo interactivo (1024) esta escrito UNA sola vez en el flujo:
// `limiteInteractivo` de `Config base`, validado en `Config del negocio`. Aca
// solo se lee, porque quien compacta para que el boton sobreviva es `Procesar
// respuesta` y tiene que usar el mismo numero. Un item que no venga de la
// configuracion no trae el dato: entonces no se degrada por largo y queda la
// red de `¿Fallo el interactivo?`.
const LIMITE_TEXTO = 4096;         // cuerpo de un mensaje de texto (Meta)

// Una variable de plantilla no admite saltos de linea, tabuladores ni mas de
// cuatro espacios seguidos, y no puede ir vacia: Meta rechaza el envio entero.
const variable = (v, max = 60) => {
  const t = String(v ?? '').replace(/[\r\n\t]+/g, ' · ').replace(/\s{2,}/g, ' ').trim();
  return (t || 'no indicado').slice(0, max);
};
const texto = (to, cuerpo) => ({
  messaging_product: 'whatsapp', recipient_type: 'individual', to,
  type: 'text', text: { preview_url: false, body: String(cuerpo).slice(0, LIMITE_TEXTO) },
});

return $input.all().map((it, i) => {
  const e = it.json;
  const responder = e.responder !== false;
  const respuesta = String(e.respuesta ?? '').trim()
    || 'Disculpa, no pude generar la respuesta. ¿Me lo repites?';
  const textoRespaldo = String(e.textoRespaldo ?? respuesta).trim() || respuesta;

  // Un interactivo con el cuerpo demasiado largo lo rechaza Meta: se manda
  // directo como texto, con el enlace adentro. Mejor eso que un envio fallido.
  //
  // PERDER EL BOTON NO PASA EN SILENCIO. Es la unica salida hacia una persona,
  // asi que la degradacion queda anotada en los avisos del turno (se ve con
  // `scripts/ver-ejecuciones.sh`). Llegar aca con un mensaje demasiado largo es
  // un caso extremo: `Procesar respuesta` ya intento compactarlo.
  const avisos = Array.isArray(e.avisos) ? [...e.avisos] : [];
  const limiteInteractivo = Number(e.limiteInteractivo) > 0 ? Number(e.limiteInteractivo) : 0;
  let cuerpoMeta = e.cuerpoMeta && e.cuerpoMeta.type === 'interactive' ? e.cuerpoMeta : null;
  if (cuerpoMeta && limiteInteractivo
    && String(cuerpoMeta.interactive?.body?.text ?? '').length > limiteInteractivo) {
    cuerpoMeta = null;
    if (!avisos.includes('boton_perdido_por_largo')) avisos.push('boton_perdido_por_largo');
  }
  const esInteractivo = cuerpoMeta !== null;
  const cuerpoRespaldo = texto(e.from, textoRespaldo);
  // Sin interactivo: si la rama traia uno y hubo que bajarlo a texto, va el
  // respaldo -- que lleva el enlace adentro --; si nunca lo trajo, la respuesta.
  const enviado = esInteractivo ? respuesta : (e.cuerpoMeta ? textoRespaldo : respuesta);
  if (!cuerpoMeta) cuerpoMeta = texto(e.from, enviado);

  // Solo los campos del prospecto: un NIT guardado antes del 15/09 no sale.
  const bruto = e.lead ?? e.leadConocido ?? {};
  const lead = Object.fromEntries(['empresa', 'contacto', 'rubro', 'flujos', 'personalizacion', 'consulta']
    .filter((k) => bruto[k]).map((k) => [k, bruto[k]]));
  const recepcion = String(e.numeroRecepcion || '').replace(/\D/g, '');
  // A NADIE SE LE AVISA DE SU PROPIO MENSAJE (misma regla que el Demo B, #68):
  // si quien escribe es el propio numero de recepcion -- una persona de NovuChat
  // probando desde su telefono --, el aviso seria un mensaje pagado que no le
  // dice nada nuevo. En produccion los numeros difieren y no cambia nada.
  const esElMismo = recepcion !== '' && recepcion === String(e.from ?? '').replace(/\D/g, '');
  const cuerpoAviso = e.avisar === true && recepcion && !esElMismo ? {
    messaging_product: 'whatsapp', recipient_type: 'individual', to: recepcion,
    type: 'template',
    template: {
      name: e.plantillaAviso || 'solicitud_contacto',
      language: { code: 'es' },
      components: [{ type: 'body', parameters: [
        e.estadoAviso, lead.empresa, lead.contacto || e.nombrePerfil,
        lead.rubro, lead.flujos, String(e.from ?? '').replace(/\D/g, ''),
      ].map((v) => ({ type: 'text', text: variable(v) })) }],
    },
  } : null;

  const crmUrl = String(e.crmUrl ?? '').trim();
  const guardar = /^https:\/\//.test(crmUrl) && (e.guardarLead === true || e.primeraVez === true);
  const cuerpoCrm = guardar ? {
    origen: 'whatsapp',
    telefono: String(e.from ?? ''),
    nombrePerfil: String(e.nombrePerfil ?? ''),
    estado: e.estadoLead || (e.accion === 'cliente_actual' ? 'cliente_actual' : 'en_conversacion'),
    ...lead,
    ...(e.anuncio ? { anuncio: e.anuncio } : {}),
    fecha: new Date().toISOString(),
  } : null;

  return { json: {
    from: e.from,
    phoneNumberId: e.phoneNumberId,
    waGraphVersion: e.waGraphVersion || 'v26.0',
    nombrePerfil: e.nombrePerfil,
    accion: e.accion ?? (e.comercioSuspendido ? 'comercio_no_operativo' : ''),
    responder,
    respuesta: responder ? String(enviado).slice(0, LIMITE_TEXTO) : '',
    // Lo que se reporta si sale el respaldo: `Confirmar envio` no abre cuerpos.
    respuestaRespaldo: responder ? String(textoRespaldo).slice(0, LIMITE_TEXTO) : '',
    esInteractivo,
    cuerpoMeta,
    cuerpoRespaldo,
    avisar: cuerpoAviso !== null,
    cuerpoAviso,
    guardar,
    crmUrl,
    cuerpoCrm,
    avisos,
  }, pairedItem: { item: i } };
});

// CONFIRMAR ENVIO: lo unico que se da por hecho es lo que Meta ACEPTO.
//
// CORRE AL FINAL. Es el hijo mas bajo de `Salida` en el lienzo y el flujo va
// con `executionOrder: v1`: cuando llega aca ya corrieron el envio al cliente
// (y su respaldo), el aviso interno y el CRM. Por eso puede leer el resultado
// de los tres, y por eso un error aca no se lleva por delante al aviso ni al
// CRM. Si se lo sube en el lienzo, lee envios que todavia no ocurrieron.
//
// HACE CUATRO COSAS, sin ninguna llamada a Meta (lee lo que ya contesto):
//  1. Si Meta rechazo el mensaje -- el texto, o el interactivo Y su respaldo --
//     o el envio no llego a Meta, TERMINA LA EJECUCION EN ERROR con el codigo y
//     el mensaje de Meta. `Enviar a WhatsApp` usa `neverError` para poder
//     mandar el respaldo, y sin este nodo un texto rechazado terminaba en
//     «success» sin que nadie se enterara (aceptacion del 15/09/2026: Meta
//     respondio 190 por una credencial mal asignada). Asi lo encuentra
//     `scripts/ver-ejecuciones.sh --error`. El error NO lleva el texto de la
//     respuesta ni el telefono del cliente.
//  2. Solo lo que salio pasa a `Reportar mensaje (saliente)`. El servidor cuenta
//     cada saliente como una respuesta del bloque (`ingesta.ts`,
//     `mensajesVentana`): reportar uno que no salio se le facturaba al comercio.
//  3. Marca la bienvenida en los datos estaticos recien cuando Meta la acepto.
//     Marcada antes de enviar, un envio fallido dejaba a ese telefono sin los
//     botones para siempre.
//  4. Marca `avisado` recien cuando Meta acepto la PLANTILLA del aviso interno.
//     El 15/09/2026 `solicitud_contacto` todavia estaba en revision y Meta
//     rechazo el envio (132001): el flujo dio el aviso por hecho y los cuatro
//     prospectos que probaron quedaron marcados como avisados sin que nadie los
//     llamara, y sin boton para volver a pedirlo. Un aviso rechazado queda
//     anotado en los `avisos` del turno -- se ve con `scripts/ver-ejecuciones.sh`
//     -- y en la conversacion (`avisoFalla`), y el estado NO dice que se aviso:
//     el proximo turno vuelve a intentarlo (un mensaje que Meta rechaza no se
//     cobra) y el boton «Hablar con un asesor» sigue saliendo.
//     Un aviso rechazado NO termina la ejecucion en error: al cliente si se le
//     respondio, y cortar aca dejaria sin reportar esa respuesta, que es la que
//     el servidor cuenta y factura.
//     Lo mismo con el CRM: un POST rechazado se anota (`crm_rechazado`) y no
//     marca nada, porque el CRM no escribe estado; el proximo cambio del
//     prospecto lo vuelve a mandar. MENSAJES: ninguno, aca no se llama a Meta.
const sd = $getWorkflowStaticData('global');
sd.conversaciones = sd.conversaciones ?? {};

const acepto = (r) => { const s = Number(r?.statusCode); return s >= 200 && s < 300; };

// Lo que devolvio un nodo de envio; nada si no corrio.
const salidaDe = (nombre) => {
  try {
    const n = $(nombre);
    if (n.isExecuted === false) return [];
    return n.all().map((x) => x.json);
  } catch (err) {
    return [];
  }
};

// Codigo y mensaje de Meta en una linea, sin datos del cliente.
const detalle = (r, telefono) => {
  if (!r) return 'el nodo de envío no devolvió nada';
  let cuerpo = r.body;
  if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (err) { cuerpo = {}; } }
  const e = cuerpo && typeof cuerpo === 'object' && cuerpo.error && typeof cuerpo.error === 'object'
    ? cuerpo.error
    : (r.error && typeof r.error === 'object' ? r.error : {});
  const partes = [r.statusCode != null ? 'HTTP ' + r.statusCode : 'sin respuesta HTTP'];
  if (e.code != null) partes.push('código ' + e.code);
  if (e.error_subcode != null) partes.push('subcódigo ' + e.error_subcode);
  if (e.type) partes.push(String(e.type));
  if (e.fbtrace_id) partes.push('fbtrace ' + e.fbtrace_id);
  let msg = String(e.message ?? e.description ?? (typeof r.error === 'string' ? r.error : ''));
  const digitos = String(telefono ?? '').replace(/\D/g, '');
  if (digitos.length >= 6) msg = msg.split(digitos).join('[destinatario]');
  msg = msg.replace(/\s+/g, ' ').trim().slice(0, 200);
  return partes.join(', ') + (msg ? ': ' + msg : '');
};

const items = $input.all().map((x) => x.json);
// Lo que este nodo le agrega a los avisos del turno, por item.
const extra = items.map(() => []);

// --- El aviso interno y el CRM ------------------------------------------
// Emparejamiento por indice, igual que el envio: `¿Avisar a NovuChat?` deja
// pasar en orden los items con `avisar === true`, y `¿Guardar prospecto?` los
// de `guardar === true`. Va antes del retorno por telefono bloqueado: con el
// bloqueo no hay mensaje al cliente, pero el aviso a una persona si sale.
const avisosMeta = salidaDe('Avisar a NovuChat');
const guardados = salidaDe('Guardar prospecto');
let a = 0;
let g = 0;
items.forEach((s, k) => {
  if (s.avisar === true) {
    const r = avisosMeta[a++];
    const c = sd.conversaciones[s.from];
    if (acepto(r)) {
      if (c) { c.avisado = true; delete c.avisoFalla; }
    } else {
      const falla = 'aviso_rechazado: ' + detalle(r, s.from);
      extra[k].push(falla);
      if (c) c.avisoFalla = falla;
    }
  }
  // Del CRM solo se anota lo que contesto: si el nodo no corrio -- `crmUrl`
  // vacio, que es lo de hoy --, no hay nada que anotar.
  if (s.guardar === true) {
    const r = guardados[g++];
    if (r !== undefined && !acepto(r)) extra[k].push('crm_rechazado: ' + detalle(r, s.from));
  }
});

// El mismo criterio que `¿Responder?`: con el telefono bloqueado no se envio nada.
const aEnviar = items.filter((s) => s.responder !== false);
if (aEnviar.length === 0) return [];

const envios = salidaDe('Enviar a WhatsApp');
const respaldos = salidaDe('Enviar texto de respaldo');
const salen = [];
const fallas = [];
let r = 0;
aEnviar.forEach((s, k) => {
  const envio = envios[k];
  // El mismo criterio que `¿Falló el interactivo?`: solo entonces corrio el respaldo.
  const porRespaldo = Number(envio?.statusCode) >= 400 && s.esInteractivo === true;
  const final = porRespaldo ? respaldos[r++] : envio;
  const turno = 'turno ' + (s.accion || 'agente');
  if (!acepto(final)) {
    fallas.push(porRespaldo
      ? detalle(final, s.from) + ' (respaldo en texto, ' + turno + '; antes el interactivo: ' + detalle(envio, s.from) + ')'
      : detalle(final, s.from) + ' (' + (s.esInteractivo ? 'interactivo' : 'texto') + ', ' + turno + ')');
    return;
  }
  const c = sd.conversaciones[s.from];
  if (s.accion === 'bienvenida' && c) c.bienvenida = true;
  const idx = items.indexOf(s);
  salen.push({ json: {
    from: s.from,
    phoneNumberId: s.phoneNumberId,
    esInteractivo: porRespaldo ? false : s.esInteractivo === true,
    respuesta: porRespaldo ? String(s.respuestaRespaldo ?? s.respuesta ?? '') : s.respuesta,
    porRespaldo,
    avisos: [...(Array.isArray(s.avisos) ? s.avisos : []), ...extra[idx]],
  }, pairedItem: { item: idx } });
});

if (fallas.length) throw new Error('Meta rechazó el mensaje al cliente: ' + fallas.join(' | '));
return salen;
